    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Select a solution based on dominance depth and objective values
    solutions = [s for s, _ in archive]
    objectives = [o for _, o in archive]

    # Calculate dominance depth for each solution
    def calculate_dominance_depth(solutions, objectives):
        n = len(solutions)
        depth = [0] * n
        for i in range(n):
            for j in range(n):
                if i != j:
                    if (objectives[i][0] >= objectives[j][0] and objectives[i][1] >= objectives[j][1]) and not (objectives[i][0] == objectives[j][0] and objectives[i][1] == objectives[j][1]):
                        depth[j] += 1
        return depth

    depths = calculate_dominance_depth(solutions, objectives)
    # Combine objective values and dominance depth for selection
    scores = [o1 + o2 - d for (o1, o2), d in zip(objectives, depths)]
    selected_idx = np.argmax(scores)
    base_solution = solutions[selected_idx].copy()

    # Generate a neighbor using hybrid local search
    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst * base_solution)

    # Greedy move: select items with highest combined marginal gains
    marginal_gains = []
    for i in range(len(base_solution)):
        if base_solution[i] == 0:
            if current_weight + weight_lst[i] <= capacity:
                gain1 = value1_lst[i]
                gain2 = value2_lst[i]
                marginal_gains.append((gain1 + gain2, i))
        else:
            if current_weight - weight_lst[i] >= 0:
                gain1 = -value1_lst[i]
                gain2 = -value2_lst[i]
                marginal_gains.append((gain1 + gain2, i))

    # Sort by total marginal gain (both objectives)
    marginal_gains.sort(reverse=True, key=lambda x: x[0])

    # Apply the best marginal gain moves
    num_moves = min(5, len(marginal_gains))
    for _, i in marginal_gains[:num_moves]:
        if new_solution[i] == 0:
            if current_weight + weight_lst[i] <= capacity:
                new_solution[i] = 1
                current_weight += weight_lst[i]
        else:
            new_solution[i] = 0
            current_weight -= weight_lst[i]

    # Adaptive move: flip items with probability based on value-to-weight ratio
    value_ratio1 = value1_lst / (weight_lst + 1e-10)
    value_ratio2 = value2_lst / (weight_lst + 1e-10)
    combined_ratio = value_ratio1 + value_ratio2

    flip_prob = 0.1 + 0.3 * (1 - current_weight / capacity)  # Higher probability when under capacity
    for i in range(len(new_solution)):
        if random.random() < flip_prob * combined_ratio[i]:
            if new_solution[i] == 1:
                if current_weight - weight_lst[i] >= 0:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]
            else:
                if current_weight + weight_lst[i] <= capacity:
                    new_solution[i] = 1
                    current_weight += weight_lst[i]

    # Objective-balanced swap operator
    for i in range(len(new_solution)):
        if new_solution[i] == 1:
            for j in range(len(new_solution)):
                if new_solution[j] == 0 and weight_lst[i] + weight_lst[j] <= capacity:
                    # Calculate potential improvement
                    delta1 = value1_lst[j] - value1_lst[i]
                    delta2 = value2_lst[j] - value2_lst[i]
                    if delta1 > 0 and delta2 > 0:
                        # Perform swap
                        new_solution[i], new_solution[j] = new_solution[j], new_solution[i]
                        break

    return new_solution

def select_neighbor(archive: List[Tuple[np.ndarray, Tuple[float, float]]], weight_lst: np.ndarray, value1_lst: np.ndarray, value2_lst: np.ndarray, capacity: float) -> np.ndarray:
    """
    Select a promising solution from the archive and generate a neighbor solution from it.

    Args:
    archive: List of (solution, objective) pairs. Each solution is a binary numpy array (0/1) of item selections.
             Each objective is a tuple of two float values (total value1, total value2).
    weight_lst: Numpy array of shape (N, ), item weights.
    value1_lst: Numpy array of shape (N, ), item values for objective 1.
    value2_lst: Numpy array of shape (N, ), item values for objective 2.
    capacity: Maximum allowed total weight.

    Returns:
    A new neighbor solution (numpy array).
    """
    if not archive:
        raise ValueError("Archive is empty")

    # Select a base solution with weighted randomness based on objective values and dominance
    scores = []
    for sol, obj in archive:
        total_weight = np.sum(weight_lst * sol)
        if total_weight > capacity:
            scores.append(0.0)
        else:
            # Calculate dominance count
            dominance = 0
            for _, other_obj in archive:
                if (other_obj[0] > obj[0] and other_obj[1] >= obj[1]) or (other_obj[0] >= obj[0] and other_obj[1] > obj[1]):
                    dominance += 1
            # Score based on combined objective values and dominance
            score = (obj[0] + obj[1]) / (1 + dominance)
            scores.append(score)

    if all(s == 0 for s in scores):
        base_solution = random.choice(archive)[0].copy()
    else:
        probs = np.array(scores) / np.sum(scores)
        selected_idx = np.random.choice(len(archive), p=probs)
        base_solution = archive[selected_idx][0].copy()

    new_solution = base_solution.copy()
    current_weight = np.sum(weight_lst * new_solution)

    # Adaptive objective-weighted greedy exploration
    for _ in range(5):  # Number of exploration steps
        # Calculate adaptive weights based on current solution's objective values
        obj1_weight = 1.0 if np.sum(value1_lst * new_solution) < np.median([obj[0] for _, obj in archive]) else 0.7
        obj2_weight = 1.0 if np.sum(value2_lst * new_solution) < np.median([obj[1] for _, obj in archive]) else 0.7

        # Calculate weighted marginal gains
        marginal_gains = []
        for i in range(len(new_solution)):
            if new_solution[i] == 0:
                if current_weight + weight_lst[i] <= capacity:
                    gain = obj1_weight * value1_lst[i] + obj2_weight * value2_lst[i]
                    marginal_gains.append((gain, i, 1))  # 1 means add item
            else:
                if current_weight - weight_lst[i] >= 0:
                    gain = - (obj1_weight * value1_lst[i] + obj2_weight * value2_lst[i])
                    marginal_gains.append((gain, i, 0))  # 0 means remove item

        if not marginal_gains:
            break

        # Sort by marginal gains (descending)
        marginal_gains.sort(reverse=True, key=lambda x: x[0])

        # Apply the best marginal gain move
        for _, i, action in marginal_gains[:3]:  # Consider top 3 moves
            if action == 1 and new_solution[i] == 0:
                if current_weight + weight_lst[i] <= capacity:
                    new_solution[i] = 1
                    current_weight += weight_lst[i]
                    break
            elif action == 0 and new_solution[i] == 1:
                if current_weight - weight_lst[i] >= 0:
                    new_solution[i] = 0
                    current_weight -= weight_lst[i]
                    break

    # Dynamic perturbation based on solution quality
    perturbation_intensity = 0.2 if np.random.random() < 0.5 else 0.4
    for i in range(len(new_solution)):
