    objective_scores = np.array([v1 + v2 for _, (v1, v2) in archive])
    diversity_scores = np.zeros(len(archive))

    for i, (sol, _) in enumerate(archive):
        for j, (other_sol, _) in enumerate(archive):
            if i != j:
                diversity_scores[i] += np.sum(sol != other_sol)

